 if dot>.9995:return (a*(1-u)+b*u)/np.linalg.norm(a*(1-u)+b*u)
 ang=np.arccos(dot);return np.sin((1-u)*ang)/np.sin(ang)*a+np.sin(u*ang)/np.sin(ang)*b
